mapper.select:
SELECT id, user_id AS userId, article_id AS articleId, deleted, created_at AS createdAt, updated_at AS updatedAt
FROM user_article_favorites
WHERE user_id = #{userId}
  AND article_id = #{articleId}
LIMIT 1

mapper.update:
UPDATE user_article_favorites
SET deleted = 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND article_id = #{articleId}
  AND deleted = 0
